// 회의 (s, e)들 중 겹치지 않게 고를 수 있는 최대 개수
sort(meet.begin(), meet.end(), [](auto& x, auto& y) {
    if (x.e != y.e) return x.e < y.e;      // 끝나는 시각 순
    return x.s < y.s;
});
int cnt = 0, last = 0;                     // last: 마지막으로 고른 회의가 끝나는 시각
for (auto& m : meet)
    if (m.s >= last) { cnt++; last = m.e; }

